#include "tom_auto_reply.h"
#include "structured_contract.h"
#include "composition_plan.h"
#include <QRegularExpression>
#include <QJsonDocument>
#include <QJsonArray>
#include <QStringList>
#include <QSet>
#include <cmath>
#include <stdexcept>
namespace companion {namespace {
void need(bool ok){if(!ok)throw std::runtime_error("tom-automatic-reply-schema");}
void keys(const QJsonObject& o,QStringList names){auto actual=o.keys();actual.sort();names.sort();need(actual==names);}
void text(QJsonValue v,int max,bool empty=false){need(v.isString()&&v.toString().size()<=max&&!v.toString().contains(QChar(0))&&(empty||!v.toString().trimmed().isEmpty()));}
void unit(QJsonValue v){need(v.isDouble()&&std::isfinite(v.toDouble())&&v.toDouble()>=0&&v.toDouble()<=1);}
QJsonObject object(QJsonValue v){need(v.isObject());return v.toObject();}
QJsonArray array(QJsonValue v,int max,int min=0){need(v.isArray()&&v.toArray().size()>=min&&v.toArray().size()<=max);return v.toArray();}
/* Only the first top-level response string may stream. Nested prompt/text keys are never interpreted as an answer. */
QString prefix(const QString& s){qsizetype i=0;auto space=[&]{while(i<s.size()&&s[i].isSpace())++i;};space();if(i==s.size()||s[i++]!='{')return {};space();const QString key="\"response\"";if(s.mid(i,key.size())!=key)return {};i+=key.size();space();if(i==s.size()||s[i++]!=':')return {};space();if(i==s.size()||s[i++]!='"')return {};QString out;while(i<s.size()){QChar c=s[i++];if(c=='"')break;if(c.unicode()<32)return {};if(c=='\\'){if(i>=s.size())break;const QChar e=s[i++];if(e=='u'){if(i+4>s.size())break;bool ok=false;ushort code=s.mid(i,4).toUShort(&ok,16);if(!ok)return {};i+=4;c=QChar(code);if(c.isHighSurrogate()){if(i+6>s.size())break;if(s.mid(i,2)!="\\u")return {};ushort low=s.mid(i+2,4).toUShort(&ok,16);if(!ok||!QChar(low).isLowSurrogate())return {};out+=c;out+=QChar(low);i+=6;continue;}if(c.isLowSurrogate())return {};}else{const QString codes="\"\\/bfnrt",decoded=QString::fromUtf16(u"\"\\/\b\f\n\r\t");auto at=codes.indexOf(e);if(at<0)return {};c=decoded[at];}}else if(c.isHighSurrogate()){if(i==s.size())break;if(!s[i].isLowSurrogate())return {};out+=c;out+=s[i++];continue;}else if(c.isLowSurrogate())return {};out+=c;}return out;}
void visual(const QJsonObject& v){const auto type=v.value("type").toString();if(type=="bar_chart"||type=="line_graph"){keys(v,{"type","title","values"});text(v.value("title"),128,true);for(auto value:array(v.value("values"),12,1)){const auto row=object(value);keys(row,{"label","value"});text(row.value("label"),32);need(row.value("value").isDouble()&&std::isfinite(row.value("value").toDouble()));}}
 else if(QStringList{"diagram","flowchart","timeline","mind_map"}.contains(type)){keys(v,{"type","title","nodes","edges"});text(v.value("title"),128,true);QSet<QString> ids;for(auto value:array(v.value("nodes"),12,1)){const auto node=object(value);keys(node,{"id","label"});text(node.value("id"),32);text(node.value("label"),64);const auto id=node.value("id").toString();need(!ids.contains(id));ids.insert(id);}for(auto value:array(v.value("edges"),24)){const auto edge=object(value);keys(edge,{"from","to","label"});need(ids.contains(edge.value("from").toString())&&ids.contains(edge.value("to").toString()));text(edge.value("label"),64,true);}}
 else if(type=="artwork"){keys(v,{"type","prompt","detailed","labels","arrows"});text(v.value("prompt"),1200);need(v.value("detailed").isBool());for(auto value:array(v.value("labels"),16)){const auto label=object(value);keys(label,{"text","x","y"});text(label.value("text"),64);unit(label.value("x"));unit(label.value("y"));}for(auto value:array(v.value("arrows"),16)){const auto arrow=object(value);keys(arrow,{"from","to"});for(const auto& key:{"from","to"}){auto point=array(arrow.value(key),2,2);unit(point[0]);unit(point[1]);}}}else need(false);}
}
AutomaticReply automaticReply(const QString& raw,bool complete,unsigned schemaVersion){need((schemaVersion==1||schemaVersion==2)&&raw.size()<=(schemaVersion==1?32000:128000));if(!complete){if(schemaVersion==1)return {prefix(raw),{},false,{}};const auto match=QRegularExpression(R"rx(^\s*\{\s*"mode"\s*:\s*"(text|visual)"\s*,\s*"response"\s*:)rx" ).match(raw);if(!match.hasMatch())return {};const auto mode=match.captured(1);return {mode=="text"?prefix(QStringLiteral("{\"response\":")+raw.mid(match.capturedEnd())):QString(),{},false,mode};}QJsonParseError error;const auto doc=QJsonDocument::fromJson(raw.toUtf8(),&error);need(error.error==QJsonParseError::NoError&&doc.isObject());const auto o=doc.object();if(schemaVersion==1)keys(o,{"response","visual"});else keys(o,{"mode","response","visual"});text(o.value("response"),16000,true);AutomaticReply result{o.value("response").toString(),{},true,schemaVersion==1?QString():o.value("mode").toString()};if(schemaVersion==2)need(QStringList{"text","visual"}.contains(result.mode));if(o.value("visual").isNull()){need(!result.response.trimmed().isEmpty()&&(schemaVersion==1||result.mode=="text"));return result;}result.visual=object(o.value("visual"));need(result.response.trimmed().isEmpty());if(schemaVersion==1)visual(result.visual);else{need(result.visual.value("version").toDouble()==2||result.visual.value("version").toDouble()==3||result.visual.value("version").toDouble()==4);if(result.visual.value("version")==4)need(result.visual.value("kind")=="picture");need(result.mode=="visual");if(result.visual.value("kind")=="picture")result.visual=lowerPicturePlan(result.visual);if(result.visual.value("kind")=="composition")result.visual=lowerCompositionDraft(result.visual);validateStructuredVisual(result.visual);}return result;}
QString automaticDisplay(const QString& raw,bool complete,unsigned schemaVersion){const auto r=automaticReply(raw,complete,schemaVersion);if(r.visual.isEmpty())return r.response;const auto v=r.visual;QStringList lines;if(schemaVersion==2){lines<<v.value("title").toString();if(lines.first().isEmpty())lines[0]="Tom drawing ("+v["category"].toString()+")";for(auto value:v["objects"].toArray()){auto o=value.toObject();if(o["kind"]=="label")lines<<o["content"].toObject()["text"].toString();}for(auto value:v["datasets"].toArray())lines<<QString("%1: %2 records").arg(value.toObject()["id"].toString()).arg(value.toObject()["rows"].toArray().size());return lines.join('\n');}const auto title=v.value("title").toString();if(!title.isEmpty())lines<<title;if(v.value("type")=="artwork"){lines<<v.value("prompt").toString();for(auto l:v.value("labels").toArray())lines<<l.toObject().value("text").toString();}else if(v.contains("values"))for(auto item:v.value("values").toArray()){auto row=item.toObject();lines<<row.value("label").toString()+": "+QString::number(row.value("value").toDouble(),'g',17);}else for(auto item:v.value("nodes").toArray())lines<<item.toObject().value("label").toString();return lines.join('\n');}
}
